         tmp7 = -tmp4
         tmp8 = tmp3 + tmp7
         tmp9 = -tmp8
         tmp10 = vn + tmp9
         tmp11 = sum(state%cx_s15*tmp10)
         energy = energy + tmp11
      end if

      state%cx_ready = 3
   end subroutine dpcm_original_complex_solve

