   !> DPCM, original form (gaussian charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs dpcm_original_complex_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] dxi  direction for xi
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_xi  hessian times direction, xi block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_tangent(state, dr, dn, dk1, dk2, dxi, da, dv, dvn, hvp_r, &
                                            hvp_n, hvp_k1, hvp_k2, hvp_xi, hvp_a, hvp_v, hvp_vn, &
                                            error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for xi
      real(wp), contiguous, intent(in) :: dxi(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      complex(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, r block
      complex(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      complex(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      complex(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      complex(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, xi block
      complex(wp), contiguous, intent(out) :: hvp_xi(:, :)
      !> Hessian times direction, a block
      complex(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      complex(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call dpcm_original_complex_mf_tangent(state, dr, dn, dk1, dk2, dxi, da, dv, dvn, hvp_r, &
                                               hvp_n, hvp_k1, hvp_k2, hvp_xi, hvp_a, hvp_v, &
                                               hvp_vn, error)
         return
      end if
      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_complex_tangent] call dpcm_original_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dxi: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_xi) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_xi: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[dpcm_original_complex_tangent] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call dpcm_original_complex_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                                dk2(:, blk), dxi(:, blk), da(:, blk), dv(:, blk), &
                                                dvn(:, blk), hvp_r(:, :, blk), hvp_n(:, :, blk), &
                                                hvp_k1(:, blk), hvp_k2(:, blk), hvp_xi(:, blk), &
                                                hvp_a(:, blk), hvp_v(:, blk), hvp_vn(:, blk), &
                                                error)
         if (allocated(error)) return
      end do
   end subroutine dpcm_original_complex_tangent

