      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:)
      real(wp) :: tmp6, tmp7, tmp8
      complex(wp), allocatable :: tmp2(:), tmp3(:), tmp4(:), tmp9(:), tmp140(:), tmp141(:), &
                                  tmp142(:), tmp143(:)
