      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%xi => state%xi
      state%op4%c2 => state%s5
      call state%solver%solve_complex(state%op4, .false., vn, state%cx_s13, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op4, .true., v, state%cx_s14, error)
