                     real(wp) :: tmp20, tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, tmp31, tmp32, &
                                 tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, &
                                 tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, tmp48
                     complex(wp) :: tmp49

                     tmp23 = state%r(1, i) + tmp22
                     tmp24 = tmp23**(2)
                     tmp26 = state%r(2, i) + tmp25
                     tmp27 = tmp26**(2)
                     tmp28 = tmp24 + tmp27
                     tmp30 = state%r(3, i) + tmp29
                     tmp31 = tmp30**(2)
                     tmp32 = tmp28 + tmp31
                     tmp33 = tmp21*tmp32
                     tmp34 = state%xi(i)**(2)
                     tmp35 = tmp33*tmp34
                     tmp36 = tmp34 + tmp21
                     tmp37 = (-81.0_wp)*tmp36
                     tmp38 = tmp35 + tmp37
                     tmp20 = 0.5_wp + sign(0.5_wp, tmp38)
                     tmp10(i) = tmp20
                     tmp39 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp38))
                     tmp40 = tmp32 + tmp39
                     tmp41 = 1.0_wp/sqrt(tmp40)
                     tmp42 = tmp41**(3)
                     tmp43 = tmp17*tmp23
                     tmp44 = tmp26*tmp18
                     tmp45 = tmp43 + tmp44
                     tmp46 = tmp30*tmp19
                     tmp47 = tmp45 + tmp46
                     tmp48 = tmp42*tmp47
                     tmp49 = tmp48*state%cx_s13(i)
                     tmp11 = tmp11 + tmp49*tmp20
