               end do
               do i = 1, npt
                  if (i == j) cycle
                  block
                     real(wp) :: tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57, tmp58, &
                                 tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, tmp66, tmp67, &
                                 tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, tmp75, tmp76, &
                                 tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, tmp85, &
                                 tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, tmp93, tmp94, &
                                 tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, tmp101, tmp102, &
                                 tmp103, tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, tmp110, &
                                 tmp111, tmp112, tmp113, tmp114, tmp115, tmp116, tmp117, tmp118, &
                                 tmp119, tmp120, tmp121, tmp122, tmp123, tmp124, tmp125, tmp126, &
                                 tmp127, tmp128, tmp129, tmp130, tmp131, tmp132, tmp133, tmp134, &
                                 tmp135, tmp136, tmp137, tmp138
                     complex(wp) :: tmp139

                     if (tmp10(i) < 0.5_wp) then
                        tmp50 = state%xi(i)**(2)
                        tmp51 = tmp50 + tmp21
                        tmp52 = 0.25_wp*tmp51
                        tmp53 = state%r(1, i) + tmp22
                        tmp54 = tmp53**(2)
                        tmp55 = state%r(2, i) + tmp25
                        tmp56 = tmp55**(2)
                        tmp57 = tmp54 + tmp56
                        tmp58 = state%r(3, i) + tmp29
                        tmp59 = tmp58**(2)
                        tmp60 = tmp57 + tmp59
                        tmp61 = tmp21*tmp60
                        tmp62 = tmp61*tmp50
                        tmp63 = -tmp62
                        tmp64 = tmp52 + tmp63
                        if (tmp64 >= 0.0_wp) then
