                           tmp132 = tmp130**(2)
                           tmp133 = -tmp132
                           tmp134 = exp(tmp133)
                           tmp135 = tmp129*tmp134
                           tmp136 = tmp135*tmp13
                           tmp137 = (-1.1283791670955126_wp)*tmp136
                           tmp138 = tmp131 + tmp137
