      state%cx_ready = 3
   end subroutine dpcm_original_complex_mf_solve

   !> DPCM, original form (gaussian charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs dpcm_original_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of dpcm_original
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_xi  partial derivative of the energy with respect to xi
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine dpcm_original_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_xi, &
                                               grad_a, grad_eps, error)
      !> State of dpcm_original
      type(dpcm_original_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to xi
      complex(wp), contiguous, intent(out) :: grad_xi(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5
      complex(wp), allocatable :: tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:), tmp11(:), &
                                  tmp12(:), tmp13(:), tmp481(:), tmp482(:), tmp483(:), tmp484(:)
      complex(wp) :: tmp485, tmp486, tmp487, tmp488, tmp489
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[dpcm_original_complex_mf_weights] call dpcm_original_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_xi) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_xi: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp481(npt), stat=stat)
      if (stat == 0) allocate (tmp482(npt), stat=stat)
      if (stat == 0) allocate (tmp483(npt), stat=stat)
      if (stat == 0) allocate (tmp484(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[dpcm_original_complex_mf_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%n => state%n
      state%op4%k1 => state%k1
      state%op4%k2 => state%k2
      state%op4%xi => state%xi
      state%op4%c2 => state%s5
      state%cx_s6 = state%r(1, :)
      state%cx_s7 = state%r(2, :)
      state%cx_s8 = state%r(3, :)
      state%cx_s9 = state%n(1, :)
      state%cx_s10 = state%n(2, :)
      state%cx_s11 = state%n(3, :)
      state%cx_s16 = state%cx_s13*state%cx_s15
      do i = 1, npt
         tmp1 = (-0.19947114020071635_wp)*state%xi(i)
         state%cx_s17(i) = tmp1
      end do
      do i = 1, npt
         tmp2 = state%k1(i) + state%k2(i)
         tmp3 = (-0.19947114020071635_wp)*tmp2
         state%cx_s18(i) = tmp3
      end do
      state%cx_s19 = (-3.141592653589793_wp)*state%cx_s3
